/* ---------------- restaurants (platform overlay on the shared restaurant fixtures) ---------------- */
export type RestaurantSeed = { organizationId: string; organizationName: string; status: AdminRestaurantStatus; createdAt: string; ordersTotal: number; docs?: Array<[string, VerificationDocument['status']]>; notes?: Array<{ at: string; by: string; text: string }> }
const DOC_KINDS: Record<string, string> = { business_registration: 'Business registration', food_licence: 'Food safety licence', tax_registration: 'Tax registration', bank_account: 'Bank account (settlement)', owner_id: 'Owner identity', insurance: 'Public liability insurance' }
/** Market-configured requirement sets (which documents a restaurant must submit depends on the market). */
export const DOC_REQUIREMENTS: Record<string, string[]> = { IN: ['business_registration', 'food_licence', 'tax_registration', 'bank_account', 'owner_id'], US: ['business_registration', 'food_licence', 'tax_registration', 'bank_account'], GB: ['business_registration', 'food_licence', 'bank_account', 'insurance'], JP: ['business_registration', 'food_licence', 'bank_account'], FR: ['business_registration', 'food_licence', 'tax_registration', 'bank_account'], AE: ['business_registration', 'food_licence', 'bank_account', 'owner_id'] }
export const docsFor = (country: string, statuses: Partial<Record<string, VerificationDocument['status']>>, base: Date): VerificationDocument[] =>
  (DOC_REQUIREMENTS[country] ?? DOC_REQUIREMENTS.US).map((kind, i) => { const st = statuses[kind] ?? 'NOT_SUBMITTED'; return { id: `${kind}`, kind, label: DOC_KINDS[kind] ?? kind, required: true, status: st, submittedAt: st === 'NOT_SUBMITTED' ? null : rel(base, -(1440 * (i + 3))), expiresAt: kind === 'food_licence' && st !== 'NOT_SUBMITTED' ? (st === 'EXPIRED' ? rel(base, -1440 * 20) : rel(base, 1440 * 365)) : null, note: st === 'REJECTED' ? 'Document unreadable — please upload a clear scan.' : null } })

/** Onboarding-only restaurants: they exist for the platform (pipeline) but are not customer-visible until approved. */
const clone = (base: Restaurant, patch: Partial<Restaurant> & { id: string; name: string; countryCode: string; timezone: string; currency: string; locality: string; adminArea: string; formatted: string }): Restaurant => {
  const { locality, adminArea, formatted, ...rest } = patch
  return { ...base, ...rest, publicId: `rst_${patch.id}`, slug: patch.id, images: [], image: '', fallback: patch.name.slice(0, 2).toUpperCase(), rating: 0, reviewCount: 0, status: 'inactive', acceptingOrders: false, market: `${patch.countryCode}-${adminArea.replace(/\s+/g, '-').toLowerCase()}`, address: { formatted, locality, adminArea, countryCode: patch.countryCode } }
}
